# A synthetic landscape in the mapfile syntax of MapServer 8: land use, rivers, roads, and named
# places over 4000 × 2500 map units, generated by scripts/generate-example.sh. Classes are picked by
# expressions on the features' properties, the smaller roads show only from a scale on, and the
# places are labelled with the font of fonts.lst, which the page hands to the bindings beside the
# mapfile; the label cache decides at every scale which names stand, the larger places first.
MAP
  NAME "sample"
  EXTENT 0 0 4000 2500
  SIZE 640 400
  IMAGECOLOR "#eef0e6"
  FONTSET "fonts.lst"

  SYMBOL
    NAME "circle"
    TYPE ELLIPSE
    FILLED TRUE
    POINTS 1 1 END
  END
  SYMBOL
    NAME "square"
    TYPE VECTOR
    FILLED TRUE
    POINTS 0 0 1 0 1 1 0 1 0 0 END
  END
  SYMBOL
    NAME "arrow"
    TYPE VECTOR
    POINTS 0 0 1 0.5 0 1 END
  END
  SYMBOL
    NAME "hatch"
    TYPE HATCH
  END

  LAYER
    NAME "landuse"
    TYPE POLYGON
    STATUS ON
    DATA "landuse.geojson"
    CLASSITEM "kind"
    CLASS
      NAME "wheat"
      EXPRESSION ("[kind]" = "field" AND [crop] = 1)
      STYLE
        COLOR 240 228 180
        OUTLINECOLOR 200 188 140
        WIDTH 0.8
      END
    END
    CLASS
      NAME "grass"
      EXPRESSION ("[kind]" = "field" AND [crop] = 2)
      STYLE
        COLOR 218 232 180
        OUTLINECOLOR 190 200 150
        WIDTH 0.8
      END
    END
    CLASS
      NAME "fallow"
      EXPRESSION ("[kind]" = "field" AND [crop] = 3)
      STYLE
        COLOR 232 218 196
        OUTLINECOLOR 200 184 160
        WIDTH 0.8
      END
    END
    CLASS
      NAME "forest"
      EXPRESSION "forest"
      STYLE
        COLOR 172 204 150
      END
    END
    CLASS
      NAME "park"
      EXPRESSION "park"
      STYLE
        COLOR 200 228 176
        OUTLINECOLOR 120 160 100
        WIDTH 1
      END
    END
    CLASS
      NAME "wetland"
      EXPRESSION "wetland"
      STYLE
        COLOR 216 232 226
      END
      STYLE
        SYMBOL "hatch"
        COLOR 110 160 190
        SIZE 6
        WIDTH 1
        ANGLE 45
      END
    END
    CLASS
      NAME "residential"
      EXPRESSION "residential"
      STYLE
        COLOR 224 212 206
        OUTLINECOLOR 196 180 172
        WIDTH 1
      END
    END
    CLASS
      NAME "water"
      EXPRESSION "water"
      STYLE
        COLOR 150 192 228
        OUTLINECOLOR 100 150 200
        WIDTH 1
      END
    END
  END

  LAYER
    NAME "rivers"
    TYPE LINE
    STATUS ON
    DATA "rivers.geojson"
    COMPOSITE
      OPACITY 85
    END
    CLASS
      NAME "river"
      EXPRESSION ([order] = 3)
      STYLE
        COLOR 100 150 200
        WIDTH 6
        LINECAP ROUND
        LINEJOIN ROUND
      END
    END
    CLASS
      NAME "tributary"
      EXPRESSION ([order] = 2)
      STYLE
        COLOR 100 150 200
        WIDTH 3.5
        LINECAP ROUND
        LINEJOIN ROUND
      END
    END
    CLASS
      NAME "stream"
      EXPRESSION ([order] = 1)
      MAXSCALEDENOM 12000
      STYLE
        COLOR 100 150 200
        WIDTH 1.5
        LINECAP ROUND
        LINEJOIN ROUND
      END
    END
  END

  LAYER
    NAME "buildings"
    TYPE POLYGON
    STATUS ON
    DATA "buildings.geojson"
    MAXSCALEDENOM 3000
    CLASSITEM "kind"
    CLASS
      NAME "block"
      EXPRESSION "block"
      STYLE
        COLOR 200 184 176
        OUTLINECOLOR 170 150 140
        WIDTH 0.8
      END
    END
    CLASS
      NAME "house"
      EXPRESSION "house"
      MAXSCALEDENOM 2000
      STYLE
        COLOR 190 160 150
        OUTLINECOLOR 140 110 100
        WIDTH 0.8
      END
    END
  END

  LAYER
    NAME "roads"
    TYPE LINE
    STATUS ON
    DATA "roads.geojson"
    CLASSITEM "kind"
    CLASS
      NAME "street"
      EXPRESSION "street"
      MAXSCALEDENOM 2000
      STYLE
        COLOR 190 180 176
        WIDTH 3
      END
      STYLE
        COLOR 255 255 255
        WIDTH 1.8
      END
    END
    CLASS
      NAME "track"
      EXPRESSION "track"
      MAXSCALEDENOM 4000
      STYLE
        COLOR 140 100 60
        WIDTH 1.2
        PATTERN 5 3 END
        LINECAP BUTT
      END
      STYLE
        SYMBOL "circle"
        GEOMTRANSFORM "start"
        COLOR 140 100 60
        SIZE 4
      END
    END
    CLASS
      NAME "minor road"
      EXPRESSION "minor"
      MAXSCALEDENOM 4000
      STYLE
        COLOR 150 150 150
        WIDTH 3.5
      END
      STYLE
        COLOR 255 255 255
        WIDTH 2
      END
    END
    CLASS
      NAME "secondary road"
      EXPRESSION "secondary"
      MAXSCALEDENOM 12000
      STYLE
        COLOR 150 130 80
        WIDTH 4.5
      END
      STYLE
        COLOR 255 236 150
        WIDTH 2.8
      END
    END
    CLASS
      NAME "primary road"
      EXPRESSION "primary"
      STYLE
        COLOR 160 100 60
        WIDTH 5
      END
      STYLE
        COLOR 250 190 110
        WIDTH 3.2
      END
    END
    CLASS
      NAME "motorway"
      EXPRESSION "motorway"
      STYLE
        COLOR 140 60 60
        WIDTH 6.5
      END
      STYLE
        COLOR 230 120 110
        WIDTH 4.5
      END
      STYLE
        SYMBOL "arrow"
        COLOR 140 60 60
        SIZE 5
        WIDTH 1
        GAP -80
        INITIALGAP 40
      END
    END
  END

  LAYER
    NAME "places"
    TYPE POINT
    STATUS ON
    DATA "places.geojson"
    LABELITEM "name"
    CLASS
      NAME "city"
      EXPRESSION ([population] >= 100000)
      STYLE
        SYMBOL "square"
        COLOR 120 40 40
        OUTLINECOLOR 255 255 255
        SIZE [size]
        WIDTH 1.5
      END
      LABEL
        FONT "sans"
        SIZE 12
        COLOR 30 30 30
        OUTLINECOLOR 255 255 255
        OUTLINEWIDTH 3
        POSITION AUTO
        PRIORITY ([population] ^ 0.2 - 1)
      END
    END
    CLASS
      NAME "town"
      EXPRESSION ([population] >= 10000)
      STYLE
        SYMBOL "circle"
        COLOR 160 50 50
        OUTLINECOLOR 255 255 255
        SIZE [size]
        WIDTH 1.5
      END
      LABEL
        FONT "sans"
        SIZE 10
        COLOR 40 40 40
        OUTLINECOLOR 255 255 255
        OUTLINEWIDTH 2
        POSITION AUTO
        PRIORITY ([population] ^ 0.2 - 1)
      END
    END
    CLASS
      NAME "village"
      EXPRESSION ([population] >= 1000)
      STYLE
        SYMBOL "circle"
        COLOR 90 90 90
        OUTLINECOLOR 255 255 255
        SIZE [size]
        WIDTH 1
      END
      LABEL
        FONT "sans"
        SIZE 8.5
        COLOR 50 50 50
        OUTLINECOLOR 255 255 255
        OUTLINEWIDTH 2
        POSITION AUTO
        PRIORITY ([population] ^ 0.2 - 1)
        WRAP " "
        MAXLENGTH 10
        ALIGN CENTER
      END
    END
    CLASS
      NAME "hamlet"
      MAXSCALEDENOM 12000
      STYLE
        SYMBOL "circle"
        COLOR 110 110 110
        SIZE [size]
      END
      LABEL
        FONT "sans"
        SIZE 7
        COLOR 90 90 90
        OUTLINECOLOR 255 255 255
        OUTLINEWIDTH 1
        POSITION AUTO
        PRIORITY ([population] ^ 0.2 - 1)
        WRAP " "
        MAXLENGTH 8
        ALIGN CENTER
      END
    END
    # Past that scale, a hamlet falls through to this class: its marker without a label.
    CLASS
      NAME "hamlet, unlabelled"
      STYLE
        SYMBOL "circle"
        COLOR 110 110 110
        SIZE [size]
      END
    END
  END
END
